        options = options || {}
        var type = options.type || 'info'
        var duration = options.duration || 3000
        var action = options.action || null

        var container = document.getElementById('toast-container')
        if (!container) return

        var toast = document.createElement('div')
        var accents = {
          success: 'border-l-green-500',
          error: 'border-l-red-500',
          warning: 'border-l-yellow-500',
          info: 'border-l-blue-500',
        }
        toast.className =
          'pointer-events-auto max-w-sm w-full px-4 py-3 rounded-lg shadow-lg border border-gray-100 dark:border-gray-700 border-l-4 bg-white dark:bg-gray-800 text-sm font-medium text-gray-900 dark:text-gray-100 transition-all duration-300 translate-x-full opacity-0 ' +
          (accents[type] || accents.info)

        if (action) {
          var a = document.createElement('a')
          a.href = action.href
          a.className = 'flex items-center justify-between gap-2'
          var msgSpan = document.createElement('span')
          msgSpan.textContent = message
          var labelSpan = document.createElement('span')
          labelSpan.className = 'text-blue-600 dark:text-blue-400 font-semibold whitespace-nowrap'
          labelSpan.textContent = action.label
          a.appendChild(msgSpan)
          a.appendChild(labelSpan)
          toast.appendChild(a)
        } else {
          toast.textContent = message
          toast.style.cursor = 'pointer'
        }

        container.appendChild(toast)
        requestAnimationFrame(function () {
          toast.classList.remove('translate-x-full', 'opacity-0')
        })

        var timer = setTimeout(function () {
          toast.classList.add('translate-x-full', 'opacity-0')
          setTimeout(function () {
            toast.remove()
          }, 300)
        }, duration)

        if (!action) {
          toast.addEventListener('click', function () {
            clearTimeout(timer)
            toast.classList.add('translate-x-full', 'opacity-0')
            setTimeout(function () {
              toast.remove()
            }, 300)
          })
        }
      }

      window.sendNotification = function (title, body, url) {
        if (localStorage.getItem('browserNotifications') !== 'true') return
        if (!('Notification' in window) || Notification.permission !== 'granted') return
        if (document.hasFocus()) return
        var n = new Notification(title, {
          body: body,
          icon: '/web-app-manifest-192x192.png',
        })
        if (url) {
          n.addEventListener('click', function () {
            window.focus()
            window.location.href = url
          })
        }
      }

